@startuml

class MasterCourse {
  + Name : string
}

class Edition {
  + ParticipantsCount : int
}

class Lesson {
  + Date : date
  + StartTime : time
  + Duration : int
  + Room : string
}

class Resource {
  + Name : string
}

class Teacher {
  + Name : string
}

class InternalTeacher extends Teacher {}

class ExternalTeacher extends Teacher {}

class MasterStudent {}

class ExternalAuditor {}

MasterCourse "1" -- "0..*" Edition
Edition "1" *-- "0..*" Lesson
Lesson "0..*" -- "1..*" Teacher
MasterCourse "0..*" -- "0..1" InternalTeacher : responsible
Teacher "0..*" -- "0..*" MasterCourse : assigned

Edition "1" -- "0..*" MasterStudent
Edition "1" -- "0..*" ExternalAuditor

Lesson "0..*" -- "0..*" Resource

@enduml

